def _get_trust_credential_status_receipt_sync_history(
    self, tenant: str, query: str
) -> None:
    # GET /v1/trust/credential-status/receipt-sync/history：只读
    # 查询某同步来源（签名方）已落盘的外系统凭证状态回执消费事件
    # 在指定时点的历史页。
    # 查询参数仅允许 signer_did、at、limit、after 且均只能出现
    # 一次：signer_did 必填非空；at 缺省取该来源同步检查点
    # next_after、须为 ASCII 非负整数；limit 缺省 50、限 1..200；
    # after 缺省 0、须为 ASCII 非负整数。空值、重复、未知参数、
    # 非 ASCII 数字、符号、越界或 after>at 均 400 且仅
    # {"error":"请求非法"}；该来源未同步（含跨租户）404 仅
    # {"error":"同步来源不存在"}，at 超过检查点 409 仅
    # {"error":"同步游标冲突"}。200 键序恰为 signer_did、at、
    # events、next_after；以请求初原子快照取 cursor<=at 的事件，
    # 再按 cursor>after 升序取前 limit 项，事件键序恰为 cursor、
    # receipt_id、verifier_did、nonce、consumed_at（cursor 为正
    # 整数，其余四值为非空字符串，consumed_at 为 UTC 秒精度 Z）；
    # 空页 next_after 等于 after，否则等于末项 cursor。同一 at
    # 的分页不受后续同步影响，重启逐字节一致。
    # 纯只读：不推进检查点、不改判重索引、不记审计、不触发落盘。
    try:
        params = parse_qs(query, keep_blank_values=True)
        allowed = {"signer_did", "at", "limit", "after"}
        if set(params) - allowed:
            raise ValidationError("请求非法")

        def _single(name: str) -> Optional[str]:
            values = params.get(name)
            if values is None:
                return None
            if len(values) != 1:
                raise ValidationError("请求非法")
            return values[0]

        signer_did = _single("signer_did")
        if signer_did is None or not signer_did:
            raise ValidationError("请求非法")

        at_raw = _single("at")
        at = (
            _parse_nonneg_int(at_raw, "at")
            if at_raw is not None
            else None
        )

        limit_raw = _single("limit")
        if limit_raw is not None:
            limit = _parse_nonneg_int(limit_raw, "limit")
            if not 1 <= limit <= 200:
                raise ValidationError("请求非法")
        else:
            limit = 50

        after_raw = _single("after")
        if after_raw is not None:
            after = _parse_nonneg_int(after_raw, "after")
        else:
            after = 0

        if at is not None and after > at:
            raise ValidationError("请求非法")
    except ValidationError:
        raise ValidationError("请求非法")

    try:
        at_value, events, next_after = (
            store.list_credential_status_receipt_sync_history(
                tenant, signer_did, at, after, limit
            )
        )
    except ValidationError:
        # at 缺省时取检查点：after 超过生效 at 同样为请求非法。
        raise ValidationError("请求非法")
    self._send_json(
        200,
        {
            "signer_did": signer_did,
            "at": at_value,
            "events": events,
            "next_after": next_after,
        },
    )

def _get_trust_credential_status(
    self, tenant: str, credential_id: str, query: str
) -> None:
    # GET .../{credential_id}?issuer_did=...：issuer_did 须唯一
    # 且非空，否则 400；未同步（含他租户双键）404，跨租户不可
    # 探测。已同步仅返回 status、reason、updated_at。
    if not credential_id:
        raise ValidationError("路径缺少 credential_id")
    params = parse_qs(query, keep_blank_values=True)
    values = params.get("issuer_did")
    if values is None:
        raise ValidationError("查询参数 issuer_did 必填")
    if len(values) != 1:
        raise ValidationError("查询参数 issuer_did 只能提供一次")
    issuer_did = values[0]
    if not issuer_did:
        raise ValidationError(
            "查询参数 issuer_did 必须为非空字符串"
        )
    record = store.get_synced_credential_status(
        tenant, issuer_did, credential_id
    )
    self._send_json(
        200,
        {
            "status": record.status,

    """原子同步一页凭证状态回执消费历史（来源方导出事件）。

    协议与 sync_receipt_consumptions 完全一致（检查点推进、游标窗口、
    同位异内容、稠密连续、幂等重放、原子落盘与回滚、同步不写审计），
    但使用独立的状态空间：
    - 检查点为 self._credential_status_receipt_sync_checkpoints 的
      (tenant_id, signer_did)；
    - 同步行存于租户桶 synced_credential_status_receipt_consumption_
      events（按 signer_did）；
    - (verifier_did, nonce) 判重索引为
      synced_credential_status_receipts，与本地
      consumed_credential_status_receipts 及普通验真回执同步的
      synced_receipts 均相互独立；新行与本批、全部历史同步页或本地
      consume 记录重复均抛 ValidationError（导出内容非法）。

    全部游标与判重校验均为只读，不创建租户桶或检查点容器；内存快照
    先于任何变更，落盘失败连同空租户容器一并回滚（内存与重载状态
    一致，重试从原游标继续）。

    返回 (created, snapshot, next_after, count)，语义同普通回执同步。
    """
    with self._lock:
        # ---- 只读阶段：不创建租户桶或任何容器 ----
        existing_bucket = self._bucket_locked(tenant_id)
        events_container = (
            existing_bucket.get(
                "synced_credential_status_receipt_consumption_events",
                {},
            )
            if existing_bucket is not None
            else {}
        )
        if not isinstance(events_container, dict):
            events_container = {}
        events_by_signer_read = events_container.get(signer_did)
        checkpoints_read = (
            self._credential_status_receipt_sync_checkpoints.get(
                tenant_id
            )
        )
        cp = (
            checkpoints_read.get(signer_did)
            if checkpoints_read is not None
            else None
        )

        # ---- 检查点游标规则（非法一律 ConflictError）----
        if cp is None:
            if after != 0:
                raise ConflictError("同步游标冲突")
            covered_after = 0
        elif snapshot < cp["snapshot"]:
            # 旧快照
            raise ConflictError("同步游标冲突")
        elif snapshot == cp["snapshot"]:
            if after > cp["after"]:
                # 跳页：声称的进度超过已落盘进度
                raise ConflictError("同步游标冲突")
            covered_after = cp["after"]
        else:
            # 新快照：必须旧快照已追平且 after 衔接旧 snapshot
            if cp["after"] != cp["snapshot"] or after != cp["snapshot"]:
                raise ConflictError("同步游标冲突")
            covered_after = cp["after"]

        # ---- 行游标：窗口 + 同位内容比对 + 新区稠密连续 ----
        stored_by_cursor = (
            {
                int(row["cursor"]): row
                for row in events_by_signer_read
            }
            if events_by_signer_read
            else {}
        )
        new_rows: List[Dict[str, Any]] = []
        expected_new_cursor = covered_after + 1
        for row in events:
            cursor = int(row["cursor"])
            if cursor <= after or cursor > snapshot:
                # 窗口外（调用方已先校验，此处兜底）
                raise ValidationError("导出内容非法")
            if cursor <= covered_after:
                stored = stored_by_cursor.get(cursor)
                if stored is None or stored != row:
                    # 同位异内容（或同位行缺失）
                    raise ConflictError("同步游标冲突")
            else:
                if cursor != expected_new_cursor:
                    raise ConflictError("同步游标冲突")
                expected_new_cursor += 1
                new_rows.append(row)

        # ---- 新行 (verifier_did, nonce) 唯一性：批内 + 全部历史 ----
        local_consumed = (
            existing_bucket.get(
                "consumed_credential_status_receipts", {}
            )
            if existing_bucket is not None
            else {}
        )
        synced_index_read = (
            existing_bucket.get(
                "synced_credential_status_receipts", {}
            )
            if existing_bucket is not None
            else {}
        )
        seen_in_batch: set = set()
        for row in new_rows:
            key = (row["verifier_did"], row["nonce"])
            if key in seen_in_batch:
                raise ValidationError("导出内容非法")
            seen_in_batch.add(key)
            if (
                key[0] in local_consumed
                and key[1] in local_consumed[key[0]]
            ):
                raise ValidationError("导出内容非法")
            if (
                key[0] in synced_index_read
                and key[1] in synced_index_read[key[0]]
            ):
                raise ValidationError("导出内容非法")

        created = cp is None
        # 快照须先于任何内存变更：落盘失败时检查点、同步行、判重
        # 索引乃至首次创建的空租户容器均恢复到调用前状态。
        mem_snapshot = self._snapshot_locked()
        try:
            bucket = self._ensure_bucket_locked(tenant_id)
            events_by_signer = bucket[
                "synced_credential_status_receipt_consumption_events"
            ].setdefault(signer_did, [])
            synced_index = bucket.setdefault(
                "synced_credential_status_receipts", {}
            )
            checkpoints = (
                self._credential_status_receipt_sync_checkpoints.setdefault(
                    tenant_id, {}
                )
            )
            for row in new_rows:
                events_by_signer.append(dict(row))
                synced_index.setdefault(row["verifier_did"], {})[
                    row["nonce"]
                ] = {
                    "receipt_id": row["receipt_id"],
                    "consumed_at": row["consumed_at"],
                    "signer_did": signer_did,
                }
            events_by_signer.sort(key=lambda row: int(row["cursor"]))
            next_after = int(events[-1]["cursor"]) if events else after
            checkpoints[signer_did] = {
                "snapshot": snapshot,
                "after": max(covered_after, next_after),
            }
            self._save_locked()
        except Exception as exc:
            self._restore_locked(mem_snapshot)
            raise StorageError("存储失败") from exc
        return created, snapshot, next_after, len(events)

def list_credential_status_receipt_sync_history(
    self,
    tenant_id: str,
    signer_did: str,
    at: Optional[int] = None,
    after: int = 0,
    limit: int = 50,
) -> Tuple[int, List[Dict[str, Any]], int]:
    """只读查询某同步来源（签名方）凭证状态回执消费事件在 at 时点的页。

    语义与 list_trust_presentation_sync_history 完全一致，但读取凭证
    状态回执同步的独立状态空间：
    - 该 (tenant_id, signer_did) 在
      _credential_status_receipt_sync_checkpoints 无检查点（从未接收
      非空页，含跨租户）时抛 NotFoundError("同步来源不存在")；
    - at 为 None 时取检查点 next_after；生效 at 超过检查点抛
      ConflictError("同步游标冲突")；after 大于生效 at 抛
      ValidationError；
    - 以请求初的原子快照取
      synced_credential_status_receipt_consumption_events 中该签名方
      全部 cursor <= 生效 at 的落盘行，再按 cursor > after 升序取前
      limit 项；每项恰含 cursor/receipt_id/verifier_did/nonce/
      consumed_at；
    - 返回 (at, events, next_after)：空页 next_after 等于 after，
      否则等于末项 cursor。

    纯只读：不推进检查点、不改判重索引、不修改任何状态、不记审计、
    不触发落盘；同一 at 的分页不受后续同步影响，重启逐字节一致。
    """
    with self._lock:
        checkpoints = (
            self._credential_status_receipt_sync_checkpoints.get(
                tenant_id
            )
        )
        cp = (
            checkpoints.get(signer_did)
            if checkpoints is not None
            else None
        )
        if cp is None:
            raise NotFoundError("同步来源不存在")
        checkpoint = int(cp["after"])
        effective_at = checkpoint if at is None else at
        if effective_at > checkpoint:
            raise ConflictError("同步游标冲突")
        if after > effective_at:
            raise ValidationError("查询参数 after 不能大于 at")
        bucket = self._bucket_locked(tenant_id)
        rows: List[Dict[str, Any]] = []
        if bucket is not None:
            rows = bucket.get(
                "synced_credential_status_receipt_consumption_events",
                {},
            ).get(signer_did, [])
        picked: List[Dict[str, Any]] = []
        for row in sorted(rows, key=lambda item: int(item["cursor"])):
            cursor = int(row["cursor"])
            if cursor > effective_at:
                continue
            if cursor <= after:
                continue
            if len(picked) >= limit:
                break
            picked.append(
                {
                    "cursor": cursor,
                    "receipt_id": row["receipt_id"],
                    "verifier_did": row["verifier_did"],
                    "nonce": row["nonce"],
                    "consumed_at": row["consumed_at"],
                }
            )
        next_after = picked[-1]["cursor"] if picked else after
        return effective_at, picked, next_after

def get_trust_anchor_snapshot_signer(
    self,
    tenant_id: str,
    signer_did: str,
) -> Tuple[int, str]:
    """返回本租户活动本地 DID 的（当前密钥版本, 当前私钥 PEM）。

    供信任锚点快照（snapshot）签名使用：
    - DID 不存在（含他租户资源）抛 NotFoundError（HTTP 404）；
    - DID 已停用抛 ConflictError（HTTP 409）；
    - 取该 DID 当前密钥版本的托管私钥。
    纯只读：不修改任何状态、不记审计、不触发落盘。
    """
